import { GET } from '@/app/api/me/export/route';
import { call, TOKENS } from './helpers';

describe('GET /api/me/export', () => {
  it('exports the patient\'s own general record', async () => {
    const res = await call(GET, { token: TOKENS.ava });
    expect(res.status).toBe(200);
    expect(res.json.patient.id).toBe('pt_ava');
    expect(res.json.patient.mrn).toBeTruthy();
    expect(res.json.appointments.every((a: any) => a.id.startsWith('apt_'))).toBe(true);
    expect(res.json.appointments[0]).not.toHaveProperty('notes');
    const dirs = Object.fromEntries(res.json.messages.map((m: any) => [m.id, m.direction]));
    expect(dirs.msg_001).toBe('received');
    expect(dirs.msg_002).toBe('sent');
    expect(res.json.clinicalNotes.map((n: any) => n.id)).toEqual(['cn_001', 'cn_002']);
  });

  it('excludes psychotherapy notes, other patients\' data and staff notes', async () => {
    const res = await call(GET, { token: TOKENS.ava });
    expect(res.text).not.toContain('pn_001');
    expect(res.text).not.toContain('transference');
    expect(res.text).not.toContain('cn_003');
    expect(res.text).not.toContain('apt_002');
    expect(res.text).not.toContain('Bring sleep diary');
  });

  it('gives another patient only their own data', async () => {
    const res = await call(GET, { token: TOKENS.theo });
    expect(res.json.patient.id).toBe('pt_theo');
    expect(res.json.messages).toEqual([]);
    expect(res.text).not.toContain('cn_001');
  });

  it('refuses other roles', async () => {
    for (const t of [TOKENS.rosa, TOKENS.dana, TOKENS.hal]) {
      expect((await call(GET, { token: t })).status).toBe(403);
    }
  });

  it('requires authentication', async () => {
    expect((await call(GET)).status).toBe(401);
  });
});

